/* Lifetime Health: fever history, lifetime antibiotic metrics, illness analysis, parent entries. Every number comes from the API with its contributing record ids. */
Object.assign(S,{lh:{loaded:false,loading:false,pid:null,dash:null,ecoli:null,corr:null,parents:[],review:null,scan:null,tab:'overview',pageUrl:null,evidence:null,contrib:null,form:null,day:null}});
NAV.splice(NAV.findIndex(([k])=>k==='episodes')+1,0,['lifetime','Lifetime Health']);
ICONS.lifetime=`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12h3l2-5 4 10 3-7 2 2h4"/><circle cx="19" cy="6" r="2"/></svg>`;
const LH_TABS=[['overview','Overview'],['fever','Fever history'],['antibiotics','Antibiotics'],['illnesses','Illness by illness'],['ecoli','E. coli episodes'],['correlation','Fever ↔ antibiotic'],['parent','Add history'],['review','Review tables']];
const lhNum=v=>v===null||v===undefined?'—':v;
const lhDays=(a,b)=>{const out=[];if(!a)return out;const d=new Date(a+'T12:00:00'),e=new Date((b||a)+'T12:00:00');while(d<=e){out.push(d.toISOString().slice(0,10));d.setDate(d.getDate()+1);}return out;};
const lhStatus=s=>({prescribed_only:['Prescribed only','warn'],scheduled:['Scheduled','warn'],confirmed_administered:['Confirmed administered','ok'],unknown:['Administration unknown','gray'],not_received:['Culture-only / not received','gray']})[s]||[s,'gray'];
const lhVer=s=>s==='verified'?'<span class="lh-badge ok">Verified by you</span>':s==='rejected'?'<span class="lh-badge gray">Rejected</span>':'<span class="lh-badge warn">Needs your verification</span>';
const lhOrigin=o=>o==='parent_report'?'<span class="lh-badge parent">Parent-reported</span>':'<span class="lh-badge">Clinician-documented</span>';
const lhBtn=(label,action,extra='',cls='btn alt small')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const lhDoc=id=>S.docs.find(d=>d.id===id);
const lhRef=(id,page)=>{const d=lhDoc(id);return `${d?(d.source_ref||('#'+d.id)):('#'+id)}${page?' p'+page:''}`;};
const lhSrc=(id,page)=>id?`<button class="btn ghost small" data-action="lh-page" data-id="${id}" data-page="${page||1}">${esc(lhRef(id,page))}</button>`:'<span class="muted tiny">No source page</span>';
async function lhLoad(force=false){
 if(!S.pid||!S.token)return;const pid=S.pid;
 if(S.lh.loading)return;if(S.lh.loaded&&S.lh.pid===pid&&!force)return;
 S.lh.loading=true;
 try{const [dash,ecoli,corr,parents,review,docs]=await Promise.all(['lifetime/dashboard','lifetime/ecoli','lifetime/correlation','lifetime/parent-entries','lifetime/review-tables','documents'].map(p=>request(`/patients/${pid}/${p}`)));
  if(pid!==S.pid)return;S.docs=docs;Object.assign(S.lh,{dash,ecoli,corr,parents,review,loaded:true,pid});}
 catch(e){fail(e);S.lh.error=e.message;S.lh.loaded=true;S.lh.pid=pid;} // a failed load is remembered; the view shows a retry button instead of re-requesting on every render
 finally{S.lh.loading=false;if(S.tab==='lifetime')render();}
}
function lhTile(t){const pend=t.key==='pending'?0:t.value-t.verified_value;return `<button class="lh-tile" data-action="lh-contrib" data-key="${t.key}"><span class="lh-label">${esc(t.label)}</span><span class="lh-value">${t.value}</span>${t.key==='pending'?`<span class="lh-pending">${t.value?'Awaiting your check':'Nothing pending'}</span>`:`<span class="lh-verified">${t.verified_value} verified${pend?` · <span class="lh-pending">${pend} awaiting verification</span>`:''}</span>`}<span class="lh-sub">${esc(t.note||'Click for the records behind this number')}</span></button>`;}
function lhHeader(){const d=S.lh.dash;const p=S.patients.find(p=>p.id===S.pid);const fev=d?.fever.metrics,abx=d?.antibiotics.metrics;return `${header('FROM BIRTH TO TODAY','Lifetime Health','Every fever and every antibiotic that the available records document, with the original page behind each number.',`<button class="btn alt" data-action="lh-summary">↓ Evidence summary</button><button class="btn" data-action="lh-parent-new">＋ Add historical information</button>`)}<div class="lh-hero"><div><span class="eyebrow">DOCUMENTED IN AVAILABLE RECORDS</span><h1>${esc(p?.name||'Your child')}’s health story, page by page.</h1><p>Born ${fmt(p?.dob)} · ${d?d.coverage.documents:'…'} medical reports stored. Numbers below count only what a document or your own entry shows. Processing every page does not mean every lifetime episode is known.</p></div><div class="lh-hero-side"><div><b>${d?fev.documented_episodes.value:'…'}</b><span>fever episodes</span></div><div><b>${d?abx.A_distinct_antibiotics.value:'…'}</b><span>distinct antibiotics</span></div><div><b>${d?abx.C_exposure_days.overall_calendar_days:'…'}</b><span>confirmed exposure days</span></div></div></div><div class="lh-tabs" role="tablist">${LH_TABS.map(([k,v])=>`<button class="lh-tab ${S.lh.tab===k?'active':''}" role="tab" data-action="lh-tab" data-key="${k}">${v}</button>`).join('')}</div>`;}
function lifetimeView(){
 if(!S.lh.loaded||S.lh.pid!==S.pid){if(!S.lh.loading)setTimeout(()=>lhLoad(),0);return lhHeader()+'<div class="card"><div class="loading">Reading every documented fever and antibiotic record…</div></div>';}
 if(S.lh.error&&!S.lh.dash)return lhHeader()+`<div class="card"><div class="muted">Could not load the lifetime summary: ${esc(S.lh.error)}</div><button class="btn alt small" data-action="lh-retry">Retry</button></div>`;
 const views={overview:lhOverview,fever:lhFever,antibiotics:lhAntibiotics,illnesses:lhIllnesses,ecoli:lhEcoli,correlation:lhCorrelation,parent:lhParent,review:lhReview};
 return lhHeader()+(views[S.lh.tab]||lhOverview)();
}
/* ---------------------------------------------------------------- overview */
function lhOverview(){const d=S.lh.dash;return `<div class="lh-tiles">${d.tiles.map(lhTile).join('')}</div><div class="lh-grid2"><div class="card"><div class="sectionhead"><h2>Lifetime timeline</h2><span class="muted tiny">Birth → today</span></div>${lhGantt()}<div class="lh-legend"><span><i style="background:var(--lh-fever)"></i>Fever (clinician-documented)</span><span><i style="background:var(--lh-parent)"></i>Fever (parent-reported)</span><span><i style="background:var(--lh-abx)"></i>Antibiotic, confirmed administered</span><span><i style="background:repeating-linear-gradient(45deg,var(--lh-abx),var(--lh-abx) 3px,transparent 3px,transparent 6px)"></i>Antibiotic, prescribed only / unknown</span><span><i style="background:var(--lh-stay)"></i>Hospital stay</span></div></div><div class="stack"><div class="card"><h2>How to read these numbers</h2><ul class="muted" style="padding-left:18px;font-size:13px;line-height:1.7"><li>A prescription is not proof of administration; confirmed exposure days use only dated administration evidence.</li><li>Antibiotics that appear only on culture susceptibility reports are never counted.</li><li>Fever is counted only when a document or your own entry states it, never because paracetamol or an antibiotic was prescribed.</li><li>Illegible drug names stay in a separate "needs verification" list and are excluded from every count.</li></ul></div><div class="card"><h2>Coverage</h2><div class="lh-kv"><div><span>Reports</span>${d.coverage.documents}</div><div><span>With transcribed text</span>${d.coverage.documents_with_text}</div><div><span>Without a document date</span>${d.coverage.documents_without_record_date}</div></div><p class="lh-caption">${esc(d.warnings[0])}</p></div></div></div>`;}
function lhGantt(){const d=S.lh.dash;const p=S.patients.find(p=>p.id===S.pid);const start=new Date(p.dob+'T12:00:00'),end=new Date((d.fever.patient.today)+'T12:00:00');const span=Math.max(1,(end-start)/86400000);const W=760,L=150,R=20,rowH=22;const x=iso=>L+((new Date(iso+'T12:00:00')-start)/86400000)/span*(W-L-R);
 const rows=[];const stays=d.illnesses.illnesses.flatMap(i=>i.hospitalization);
 d.fever.episodes.forEach(f=>{if(!f.first_documented_on)return;rows.push({label:f.title,kind:'fever',origin:f.origin,approx:f.date_certainty!=='exact',a:f.first_documented_on,b:f.last_documented_on||f.first_documented_on,entity:'fever_episode',id:f.id});});
 d.antibiotics.courses.filter(c=>c.administration_status!=='not_received').forEach(c=>{const a=c.actual_start||c.prescribed_on||c.planned_start;if(!a)return;const b=c.actual_stop||c.planned_end||(c.prescribed_duration_days?new Date(new Date(a+'T12:00:00').getTime()+(c.prescribed_duration_days-1)*86400000).toISOString().slice(0,10):a);rows.push({label:`${c.generic_name} · ${c.route}`,kind:'abx',confirmed:c.administration_status==='confirmed_administered',a,b,entity:'antibiotic_course',id:c.id});});
 if(!rows.length)return empty('No dated fever or antibiotic records yet. Add historical information or verify imported transcriptions.');
 const H=30+rows.length*rowH+30;const months=[];for(let m=new Date(start.getFullYear(),start.getMonth(),1);m<=end;m.setMonth(m.getMonth()+1))months.push(new Date(m));
 return `<svg class="lh-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Lifetime timeline of fever episodes and antibiotic courses"><defs><pattern id="lh-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="3" height="6" fill="var(--lh-abx)"/></pattern></defs>${stays.map(s=>s.discharged_on?`<rect x="${x(s.admitted_on)}" y="20" width="${Math.max(2,x(s.discharged_on)-x(s.admitted_on))}" height="${H-50}" fill="var(--lh-stay)"><title>Hospital stay ${s.admitted_on} to ${s.discharged_on}</title></rect>`:'').join('')}${months.filter((m,i)=>i%2===0).map(m=>{const iso=m.toISOString().slice(0,10);const xx=x(iso);return xx>=L?`<line x1="${xx}" y1="20" x2="${xx}" y2="${H-30}" class="axis"/><text x="${xx+2}" y="14" class="muted">${m.toLocaleString('en-IN',{month:'short',year:'2-digit'})}</text>`:'';}).join('')}${rows.map((r,i)=>{const y=30+i*rowH;const x1=x(r.a),x2=Math.max(x(r.b),x1+6);const fill=r.kind==='fever'?(r.origin==='parent_report'?'var(--lh-parent)':'var(--lh-fever)'):(r.confirmed?'var(--lh-abx)':'url(#lh-hatch)');return `<g class="lh-bar-link" data-action="lh-evidence" data-entity="${r.entity}" data-id="${r.id}"><text x="0" y="${y+14}" class="lh-gantt-row">${esc(r.label.length>24?r.label.slice(0,23)+'…':r.label)}</text><rect x="${x1}" y="${y+4}" width="${x2-x1}" height="14" rx="4" fill="${fill}" ${r.approx?'stroke="var(--lh-fever)" stroke-dasharray="3 2"':''}><title>${esc(r.label)}: ${r.a} → ${r.b}${r.approx?' (approximate dates)':''}</title></rect></g>`;}).join('')}<line x1="${L}" y1="${H-30}" x2="${W-R}" y2="${H-30}" class="axis"/><text x="${L}" y="${H-12}" class="muted">Birth ${fmt(p.dob)}</text><text x="${W-R}" y="${H-12}" text-anchor="end" class="muted">Today</text></svg>`;}
/* ---------------------------------------------------------------- fever */
function lhFever(){const f=S.lh.dash.fever,m=f.metrics;const ill=S.lh.dash.illnesses.illnesses;
 return `<div class="lh-grid3"><button class="lh-metric" data-action="lh-contrib" data-key="fever_episodes"><b>${m.documented_episodes.value}</b><span>Documented fever episodes</span></button><button class="lh-metric" data-action="lh-list" data-kind="fever" data-ids="${m.episodes_with_uncertain_dates.contributors.join(',')}"><b>${m.episodes_with_uncertain_dates.value}</b><span>Episodes with uncertain dates</span></button><button class="lh-metric" data-action="lh-list" data-kind="fever" data-ids="${m.hospitalized_episodes.contributors.join(',')}"><b>${m.hospitalized_episodes.value}</b><span>Episodes with hospitalization</span></button><button class="lh-metric" data-action="lh-tab" data-key="fever"><b>${m.documented_fever_calendar_days.value}</b><span>Calendar days with documented fever</span></button><button class="lh-metric" data-action="lh-list" data-kind="fever" data-ids="${m.highest_recorded_temperature?m.highest_recorded_temperature.episode_id:''}"><b>${m.highest_recorded_temperature?m.highest_recorded_temperature.value+' °'+m.highest_recorded_temperature.unit:'—'}</b><span>Highest recorded temperature</span></button><button class="lh-metric" data-action="lh-list" data-kind="fever" data-ids="${m.longest_documented_episode?m.longest_documented_episode.episode_id:''}"><b>${m.longest_documented_episode?m.longest_documented_episode.days+' d':'—'}</b><span>Longest documented episode</span></button></div>
 <div class="card lh-section"><div class="sectionhead"><h2>Fever calendar</h2><button class="btn small" data-action="lh-fever-new">＋ Add clinician-documented episode</button></div><div class="lh-legend"><span><i style="background:var(--lh-fever)"></i>Documented fever day</span><span><i style="background:repeating-linear-gradient(45deg,var(--lh-fever),var(--lh-fever) 3px,var(--lh-fever-soft) 3px,var(--lh-fever-soft) 6px)"></i>Approximate dates</span><span><i style="background:var(--lh-parent)"></i>Parent-reported</span><span><i style="background:var(--lh-stay)"></i>Hospital stay</span><span><i style="background:var(--lh-abx);height:4px"></i>Confirmed antibiotic day</span></div>${lhCalendar()}</div>
 <div class="card lh-section"><h2>Episodes (${f.episodes.length})</h2>${f.episodes.map(e=>`<div class="lh-episode"><div class="lh-row"><h3>${esc(e.title)}</h3>${lhOrigin(e.origin)}${lhVer(e.verification_status)}${e.hospitalized?'<span class="lh-badge iv">Hospitalized</span>':''}${e.date_certainty!=='exact'?'<span class="lh-badge warn">Dates '+esc(e.date_certainty)+'</span>':''}</div><div class="lh-kv"><div><span>First documented</span>${fmt(e.first_documented_on)}</div><div><span>Last documented</span>${fmt(e.last_documented_on)}</div><div><span>Documented duration</span>${e.documented_duration_days!=null?e.documented_duration_days+' day(s)':'as written'}${e.duration_text?` · “${esc(e.duration_text)}”`:''}</div><div><span>Highest temperature</span>${e.highest_temperature?esc(e.highest_temperature)+' °'+esc(e.temperature_unit):'not recorded'}</div><div><span>Symptoms</span>${esc(e.symptoms||'not documented')}</div><div><span>Documented diagnosis</span>${esc(e.documented_diagnosis||'not documented')}</div><div><span>Antipyretics</span>${esc(e.antipyretics||'none documented')}</div><div><span>Antibiotics in this episode</span>${e.antibiotics_during_episode.length?e.antibiotics_during_episode.map(a=>`${esc(a.generic_name)} (${esc(a.route)}, ${lhStatus(a.administration_status)[0].toLowerCase()}${a.link==='date_window_only'?', linked by date only':''})`).join('; '):'none documented'}</div><div><span>Resolution documented</span>${fmt(e.resolution_documented_on)}</div><div><span>Illness episode</span>${(ill.find(i=>i.episode.id===e.illness_episode_id)||{}).episode?.title||'not linked'}</div></div>${e.needs_parent_check?`<div class="lh-flag"><b>Please check:</b> ${esc(e.needs_parent_check)}</div>`:''}${e.notes?`<p class="lh-caption">${esc(e.notes)}</p>`:''}<div class="lh-row">${lhBtn(`Original evidence (${e.evidence.length})`,'lh-evidence',`data-entity="fever_episode" data-id="${e.id}"`,'btn small')}${lhSrc(e.source_document_id,e.source_page)}${e.verification_status!=='verified'?lhBtn('✓ Verified against original','lh-verify',`data-entity="fever" data-id="${e.id}" data-status="verified"`):''}${e.verification_status!=='rejected'?lhBtn('Reject','lh-verify',`data-entity="fever" data-id="${e.id}" data-status="rejected"`,'btn ghost small'):''}${e.origin==='clinician_document'?lhBtn('Edit','lh-fever-edit',`data-id="${e.id}"`,'btn ghost small'):''}</div></div>`).join('')||empty('No fever episode is documented in the available records. Use “Add historical information” for fevers that were managed at home.')}<p class="lh-caption">${f.warnings.map(esc).join(' ')}</p></div>`;}
function lhCalendar(){const d=S.lh.dash;const p=S.patients.find(p=>p.id===S.pid);const fever={},parent={},approx={},abx=new Set(d.antibiotics.metrics.C_exposure_days.overall_dates),stay=new Set();
 d.fever.episodes.forEach(e=>e.calendar_days.forEach(day=>{(e.origin==='parent_report'?parent:fever)[day]=(fever[day]||parent[day]||[]).concat(e.id);if(e.date_certainty!=='exact')approx[day]=true;}));
 d.illnesses.illnesses.flatMap(i=>i.hospitalization).forEach(h=>lhDays(h.admitted_on,h.discharged_on||h.admitted_on).forEach(x=>stay.add(x)));
 const months=[];const start=new Date(p.dob+'T12:00:00'),end=new Date(d.fever.patient.today+'T12:00:00');for(let m=new Date(start.getFullYear(),start.getMonth(),1);m<=end;m.setMonth(m.getMonth()+1))months.push(new Date(m));
 return `<div class="lh-cal">${months.map(m=>{const y=m.getFullYear(),mo=m.getMonth();const first=new Date(y,mo,1).getDay();const n=new Date(y,mo+1,0).getDate();let cells='';for(let i=0;i<first;i++)cells+='<span></span>';for(let dd=1;dd<=n;dd++){const iso=`${y}-${String(mo+1).padStart(2,'0')}-${String(dd).padStart(2,'0')}`;const cls=['lh-day',fever[iso]?'fever':'',parent[iso]?'parent':'',approx[iso]?'approx':'',abx.has(iso)?'abx':'',stay.has(iso)?'stay':'',iso===p.dob?'birth':''].filter(Boolean).join(' ');const hit=fever[iso]||parent[iso]||abx.has(iso);cells+=hit?`<button class="${cls}" data-action="lh-day" data-day="${iso}" title="${iso}">${dd}</button>`:`<span class="${cls}">${dd}</span>`;}return `<div class="lh-month"><h4>${m.toLocaleString('en-IN',{month:'long',year:'numeric'})}</h4><div class="lh-days">${cells}</div></div>`;}).join('')}</div>`;}
/* ---------------------------------------------------------------- antibiotics */
function lhBars(data,label,color='var(--lh-abx)'){const entries=Object.entries(data);if(!entries.length)return empty('Nothing documented.');const max=Math.max(...entries.map(([,v])=>v),1);const W=520,rowH=26,L=170;return `<svg class="lh-chart" viewBox="0 0 ${W} ${entries.length*rowH+10}" role="img" aria-label="${esc(label)}">${entries.map(([k,v],i)=>`<g><text x="0" y="${i*rowH+17}">${esc(k.length>26?k.slice(0,25)+'…':k)}</text><rect x="${L}" y="${i*rowH+5}" width="${Math.max(3,(W-L-40)*v/max)}" height="16" rx="4" fill="${color}"><title>${esc(k)}: ${v}</title></rect><text x="${L+Math.max(3,(W-L-40)*v/max)+6}" y="${i*rowH+17}">${v}</text></g>`).join('')}</svg>`;}
function lhMonthly(byMonth){const months=Object.keys(byMonth);if(!months.length)return empty('No dated prescriptions.');const drugs=[...new Set(months.flatMap(m=>Object.keys(byMonth[m])))];const palette=['var(--lh-abx)','var(--lh-iv)','var(--lh-fever)','var(--lh-parent)','var(--lh-ok)','#7a8a99','#c27ba0'];const W=560,H=200,L=30,B=40;const max=Math.max(...months.map(m=>Object.values(byMonth[m]).reduce((a,b)=>a+b,0)),1);const bw=Math.min(48,(W-L-20)/months.length-8);return `<svg class="lh-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Antibiotics prescribed by month"><line x1="${L}" y1="${H-B}" x2="${W-10}" y2="${H-B}" class="axis"/>${months.map((m,i)=>{let y=H-B;const x=L+10+i*((W-L-20)/months.length);return Object.entries(byMonth[m]).map(([g,v])=>{const h=(H-B-20)*v/max;y-=h;return `<rect x="${x}" y="${y}" width="${bw}" height="${h}" fill="${palette[drugs.indexOf(g)%palette.length]}" rx="3"><title>${m}: ${esc(g)} ×${v}</title></rect>`;}).join('')+`<text x="${x+bw/2}" y="${H-B+14}" text-anchor="middle" class="muted">${m.slice(2).replace('-','/')}</text>`;}).join('')}${drugs.map((g,i)=>`<rect x="${L+i*120}" y="${H-12}" width="10" height="10" fill="${palette[i%palette.length]}"/><text x="${L+14+i*120}" y="${H-3}" class="muted">${esc(g.slice(0,16))}</text>`).join('')}</svg>`;}
function lhAntibiotics(){const a=S.lh.dash.antibiotics,m=a.metrics,ec=S.lh.ecoli;const E=m.E_status_breakdown;const exposure={};Object.entries(m.C_exposure_days.per_antibiotic).forEach(([g,v])=>exposure[g]=v.days);
 const perDrug=lhBars(m.courses_per_antibiotic,'Documented courses per antibiotic');
 const route=Object.entries(m.route_split).map(([r,v])=>`<div><span>${esc(r)}</span>${v.courses} course(s) · ${v.exposure_days} confirmed day(s)</div>`).join('');
 return `<div class="lh-tiles">${[['A','Distinct antibiotics',m.A_distinct_antibiotics.value,'distinct_antibiotics','Active ingredients; brands normalised'],['B','Antibiotic courses',m.B_antibiotic_courses.value,'antibiotic_courses',`${m.B_antibiotic_courses.continuations_merged.length} renewal/IV→oral record(s) merged`],['C','Confirmed exposure days',m.C_exposure_days.overall_calendar_days,'exposure_days',`${m.C_exposure_days.courses_without_documented_days.length} course(s) without dated administration`],['D','Documented administrations',m.D_documented_administrations.value,'administrations','Individual doses with a chart or caregiver record']].map(([k,l,v,key,n])=>`<button class="lh-tile" data-action="lh-contrib" data-key="${key}"><span class="lh-label">Metric ${k} · ${l}</span><span class="lh-value">${v}</span><span class="lh-sub">${esc(n)}</span></button>`).join('')}</div>
 <div class="card"><div class="sectionhead"><h2>Metric E · Prescribed versus actually administered</h2><button class="btn small" data-action="lh-course-new">＋ Add antibiotic record</button></div><div class="lh-grid3" style="grid-template-columns:repeat(5,minmax(0,1fr))">${[['prescribed_only','Prescribed only'],['scheduled','Scheduled'],['confirmed_administered','Confirmed administered'],['unknown','Unknown status'],['not_received','Culture-only / not received']].map(([k,l])=>`<button class="lh-metric" data-action="lh-list" data-kind="abx" data-ids="${E[k].contributors.join(',')}"><b>${E[k].value}</b><span>${l}</span></button>`).join('')}</div>${m.unclassified_candidates.value?`<div class="lh-flag"><b>${m.unclassified_candidates.value} illegible or unrecognised drug name(s)</b> are excluded from every count until verified. ${lhBtn('Show','lh-list',`data-kind="abx" data-ids="${m.unclassified_candidates.contributors.join(',')}"`)}</div>`:''}${m.C_exposure_days.undated_inpatient_windows.length?`<div class="lh-flag"><b>Hospital IV antibiotics without a dated chart:</b> ${m.C_exposure_days.undated_inpatient_windows.map(w=>`${esc(w.generic_name)} during the stay ${fmt(w.window_start)} – ${fmt(w.window_end)} (at most ${w.at_most_days} days; not counted as confirmed days)`).join('; ')}. Upload the nursing or medication-administration chart to turn these into confirmed exposure days.</div>`:''}</div>
 <div class="lh-grid2 lh-section"><div class="card"><h2>Courses per antibiotic</h2>${perDrug}<p class="lh-caption">Prescribed more than once: ${m.prescribed_more_than_once.map(esc).join(', ')||'none'}</p></div><div class="card"><h2>Confirmed exposure days per antibiotic</h2>${lhBars(exposure,'Confirmed exposure days per antibiotic','var(--lh-ok)')}<p class="lh-caption">Days with a dated administration record; the same calendar day with two agents counts once in the overall total.</p></div></div>
 <div class="lh-grid2 lh-section"><div class="card"><h2>Antibiotics prescribed by month</h2>${lhMonthly(m.by_month)}</div><div class="card"><h2>Hospital IV versus oral</h2><div class="lh-kv">${route||'<div>No courses recorded.</div>'}</div><h3 class="lh-section">E. coli-related episodes</h3>${ec.laboratory_findings.map(i=>`<div class="lh-quote">${fmt(i.observation.record_date)} · ${esc(i.specimen_type)} culture: ${esc(i.observation.organism||'E. coli')}<small>Antibiotics within −5/+21 days: ${i.antibiotics_prescribed_or_administered_within_window.map(c=>`${esc(c.generic_name)} (${esc(c.route)}, ${lhStatus(c.administration_status)[0].toLowerCase()}; report: ${esc(c.laboratory_report_says)})`).join('; ')||'none documented'}</small></div>`).join('')||'<p class="muted tiny">No E. coli culture result is recorded yet.</p>'}</div></div>
 <div class="card lh-section"><h2>Lifetime antibiotic timeline</h2>${lhCourseGantt(a.courses)}</div>
 <div class="card lh-section"><h2>All antibiotic records (${a.courses.length})</h2><div class="tablewrap"><table class="lh-table"><thead><tr><th>Antibiotic</th><th>Route · setting</th><th>Prescribed</th><th>Actual start → stop</th><th>Duration</th><th>Status</th><th>Illness</th><th>Evidence</th><th></th></tr></thead><tbody>${a.courses.map(c=>`<tr><td><b>${esc(c.generic_name)}</b>${c.brand_name?`<div class="muted tiny">${esc(c.brand_name)}</div>`:''}<div class="muted tiny">${esc(c.drug_class)}</div>${c.unclassified?'<span class="lh-badge warn">Unrecognised name · not counted</span>':''}${c.continuation_of_id?`<span class="lh-badge gray">Continuation of #${c.continuation_of_id}</span>`:''}</td><td>${esc(c.route)}<div class="muted tiny">${esc(c.setting.replaceAll('_',' '))}</div></td><td>${fmt(c.prescribed_on)}<div class="muted tiny">${esc(c.dose)} ${esc(c.frequency)}</div></td><td>${fmt(c.actual_start)} → ${fmt(c.actual_stop)}<div class="muted tiny">${c.exposure_days.length} confirmed day(s) · ${c.administrations.length} dose record(s)</div></td><td>${esc(c.prescribed_duration_text||(c.prescribed_duration_days?c.prescribed_duration_days+' days':'not documented'))}</td><td><span class="lh-badge ${lhStatus(c.administration_status)[1]}">${lhStatus(c.administration_status)[0]}</span>${c.administration_evidence==='statement_only'?'<div style="margin-top:4px"><span class="lh-badge warn">Hospital statement only · no dated chart</span></div>':''}<div style="margin-top:4px">${lhVer(c.verification_status)} ${lhOrigin(c.origin)}</div></td><td>${esc(c.illness||c.indication||'—')}</td><td>${lhBtn(`Evidence (${c.evidence.length})`,'lh-evidence',`data-entity="antibiotic_course" data-id="${c.id}"`)} ${lhSrc(c.source_document_id,c.source_page)}</td><td><div class="pillrow">${c.verification_status!=='verified'?lhBtn('✓ Verify','lh-verify',`data-entity="antibiotics" data-id="${c.id}" data-status="verified"`):''}${lhBtn('Edit','lh-course-edit',`data-id="${c.id}"`,'btn ghost small')}${c.administration_status!=='not_received'?lhBtn('＋ Dose record','lh-admin-new',`data-id="${c.id}"`,'btn ghost small'):''}</div>${c.needs_parent_check?`<div class="lh-flag">${esc(c.needs_parent_check)}</div>`:''}</td></tr>`).join('')||'<tr><td colspan="9">'+empty('No antibiotic records yet.')+'</td></tr>'}</tbody></table></div>${a.review_flags.length?`<h3 class="lh-section">Review flags (${a.review_flags.length})</h3>${a.review_flags.map(f=>`<div class="lh-flag"><b>${esc(f.type.replaceAll('_',' '))}</b> · courses ${f.course_ids.map(i=>'#'+i).join(', ')}: ${esc(f.detail)}</div>`).join('')}`:''}<p class="lh-caption">${a.warnings.map(esc).join(' ')}</p></div>`;}
function lhCourseGantt(courses){const rows=courses.filter(c=>c.administration_status!=='not_received'&&(c.actual_start||c.prescribed_on||c.planned_start));if(!rows.length)return empty('No dated antibiotic course yet.');const dates=rows.flatMap(c=>[c.actual_start,c.prescribed_on,c.planned_start,c.actual_stop,c.planned_end].filter(Boolean));const min=new Date(dates.sort()[0]+'T12:00:00'),max=new Date(dates.sort().at(-1)+'T12:00:00');min.setDate(min.getDate()-7);max.setDate(max.getDate()+10);const span=(max-min)/86400000;const W=760,L=190,R=10,rowH=24;const x=iso=>L+((new Date(iso+'T12:00:00')-min)/86400000)/span*(W-L-R);
 return `<svg class="lh-chart" viewBox="0 0 ${W} ${rows.length*rowH+36}" role="img" aria-label="Antibiotic courses over time"><defs><pattern id="lh-hatch2" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="3" height="6" fill="var(--lh-abx)"/></pattern></defs>${rows.map((c,i)=>{const a=c.actual_start||c.prescribed_on||c.planned_start;const b=c.actual_stop||c.planned_end||(c.prescribed_duration_days?new Date(new Date(a+'T12:00:00').getTime()+(c.prescribed_duration_days-1)*86400000).toISOString().slice(0,10):a);const y=i*rowH;const conf=c.administration_status==='confirmed_administered';return `<g class="lh-bar-link" data-action="lh-evidence" data-entity="antibiotic_course" data-id="${c.id}"><text x="0" y="${y+15}">${esc((c.generic_name+' · '+c.route).slice(0,30))}</text><rect x="${x(a)}" y="${y+4}" width="${Math.max(6,x(b)-x(a))}" height="15" rx="4" fill="${conf?(c.route==='IV'?'var(--lh-iv)':'var(--lh-abx)'):'url(#lh-hatch2)'}"><title>${esc(c.generic_name)} ${c.route}: ${a} → ${b} · ${lhStatus(c.administration_status)[0]}${c.exposure_days.length?' · '+c.exposure_days.length+' confirmed day(s)':''}</title></rect></g>`;}).join('')}<text x="${L}" y="${rows.length*rowH+28}" class="muted">${min.toISOString().slice(0,10)}</text><text x="${W-R}" y="${rows.length*rowH+28}" text-anchor="end" class="muted">${max.toISOString().slice(0,10)}</text></svg><div class="lh-legend"><span><i style="background:var(--lh-abx)"></i>Oral, confirmed</span><span><i style="background:var(--lh-iv)"></i>IV, confirmed</span><span><i style="background:repeating-linear-gradient(45deg,var(--lh-abx),var(--lh-abx) 3px,transparent 3px,transparent 6px)"></i>Prescribed only / unknown (planned span shown)</span></div>`;}
/* ---------------------------------------------------------------- illnesses, e. coli, correlation */
function lhIllnesses(){const ill=S.lh.dash.illnesses;return `<div class="card"><div class="sectionhead"><h2>One consolidated record per illness (${ill.illnesses.length})</h2><button class="btn small" data-action="new-episode">＋ Add illness episode</button></div>${ill.illnesses.map((i,n)=>`<div class="lh-episode"><div class="lh-row"><h3>Episode ${n+1}: ${esc(i.episode.title)}</h3><span class="lh-badge">${fmt(i.episode.started_on)} → ${fmt(i.episode.ended_on)}</span>${i.hospitalization.length?'<span class="lh-badge iv">Hospitalized</span>':''}</div><div class="lh-kv"><div><span>Symptoms</span>${esc(i.symptoms||'not documented')}</div><div><span>Documented diagnosis</span>${esc(i.documented_diagnosis||'not documented')}</div><div><span>Fever history</span>${i.fever.map(f=>`${esc(f.title)} (${fmt(f.first_documented_on)}${f.highest_temperature?', '+esc(f.highest_temperature)+'°'+esc(f.temperature_unit):''}${f.origin==='parent_report'?', parent-reported':''})`).join('; ')||'no fever documented'}</div><div><span>Prescribed antibiotics</span>${i.prescribed_antibiotics.map(c=>`${esc(c.generic_name)} ${esc(c.route)} (${lhStatus(c.administration_status)[0].toLowerCase()})`).join('; ')||'none documented'}</div><div><span>Confirmed administered</span>${i.confirmed_administered.map(c=>`${esc(c.generic_name)} ${fmt(c.actual_start)}→${fmt(c.actual_stop)} (${c.administrations} dose record(s))`).join('; ')||'none confirmed'}</div><div><span>Hospitalization</span>${i.hospitalization.map(h=>`${esc(h.facility)} ${fmt(h.admitted_on)}→${fmt(h.discharged_on)}`).join('; ')||'none'}</div></div><details><summary>Laboratory results in this window (${i.laboratory.length})</summary>${i.laboratory.map(o=>`<div class="lh-quote">${fmt(o.record_date)} · <b>${esc(o.test_name)}</b> ${esc(o.value)} ${esc(o.unit)} · ${esc(o.specimen||'specimen unknown')}${o.organism?' · organism: '+esc(o.organism):''}<small>${o.verified?'Caregiver verified':'Unverified transcription'} · ${lhSrc(o.source_document_id,o.source_page)}</small></div>`).join('')||'<p class="muted tiny">None.</p>'}</details><details><summary>Follow-up findings (${i.follow_up.length})</summary>${i.follow_up.map(f=>`<div class="lh-quote">${fmt(f.date)} · ${esc(f.kind)} · ${esc(f.title)}${f.status?' · '+esc(f.status):''}</div>`).join('')||'<p class="muted tiny">No follow-up document within 21 days.</p>'}</details>${i.episode.notes?`<p class="lh-caption">${esc(i.episode.notes)}</p>`:''}<div class="lh-row">${lhSrc(i.episode.source_document_id,i.episode.source_page)}</div></div>`).join('')||empty('No illness episode has been created yet. Add one and link its fever, antibiotic and laboratory records.')}${ill.unassigned.fever_episodes.length||ill.unassigned.antibiotic_courses.length?`<div class="lh-flag"><b>Not yet linked to an illness:</b> ${ill.unassigned.fever_episodes.map(f=>'fever “'+esc(f.title)+'”').concat(ill.unassigned.antibiotic_courses.map(c=>'antibiotic '+esc(c.generic_name)+' ('+fmt(c.prescribed_on)+')')).join('; ')}</div>`:''}<p class="lh-caption">${ill.warnings.map(esc).join(' ')}</p></div>`;}
function lhEcoli(){const e=S.lh.ecoli;return `<div class="card"><h2>E. coli-related laboratory findings (${e.laboratory_findings.length})</h2><p class="muted" style="font-size:13px">Specimen types: ${Object.entries(e.specimen_summary).map(([k,v])=>`${esc(k)} ×${v}`).join(', ')||'none'}. A laboratory finding is listed separately from a clinician-documented diagnosis.</p>${e.laboratory_findings.map(i=>`<div class="lh-episode"><div class="lh-row"><h3>${fmt(i.observation.record_date)} · ${esc(i.specimen_type)} specimen</h3><span class="lh-badge fever">${esc(i.laboratory_finding)}</span><span class="lh-badge gray">Laboratory finding, not a diagnosis</span>${i.observation.verified?'<span class="lh-badge ok">Verified transcription</span>':'<span class="lh-badge warn">Unverified transcription</span>'}</div><div class="lh-kv"><div><span>Organism</span>${esc(i.observation.organism||'as reported')}</div><div><span>Culture findings</span>${esc(i.observation.culture_findings||'see report')}</div><div><span>Fever episodes within 14 days</span>${i.fever_episodes_within_14_days.map(f=>esc(f.title)).join('; ')||'none documented'}</div></div><div><span class="muted tiny strong">SUSCEPTIBILITY AS PRINTED</span><div class="lh-sus">${['susceptible','resistant','intermediate'].flatMap(k=>i.parsed_susceptibility[k].map(g=>`<span class="${k[0].toUpperCase()}">${esc(g)} · ${k[0].toUpperCase()}</span>`)).join('')||'<span>not transcribed</span>'}</div></div><h4 style="margin:10px 0 4px">Antibiotics prescribed or administered within −5/+21 days</h4><div class="tablewrap"><table class="lh-table"><thead><tr><th>Antibiotic</th><th>Route</th><th>Date</th><th>Status</th><th>Laboratory report says</th></tr></thead><tbody>${i.antibiotics_prescribed_or_administered_within_window.map(c=>`<tr><td>${esc(c.generic_name)}</td><td>${esc(c.route)}</td><td>${fmt(c.prescribed_on)}</td><td>${lhStatus(c.administration_status)[0]}</td><td>${esc(c.laboratory_report_says)}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">No antibiotic record in this window.</td></tr>'}</tbody></table></div><div class="lh-row">${lhSrc(i.observation.source_document_id,i.observation.source_page)}</div></div>`).join('')||empty('No culture result mentioning E. coli has been recorded in Lab results yet.')}<h3 class="lh-section">Clinician-documented diagnoses mentioning E. coli (${e.clinician_documented_diagnoses_mentioning_ecoli.length})</h3>${e.clinician_documented_diagnoses_mentioning_ecoli.map(d=>`<div class="lh-quote">${esc(d.kind)} · ${fmt(d.started_on||d.admitted_on)} · ${esc(d.title||d.facility)}<small>${esc(d.documented_diagnosis)}</small></div>`).join('')||'<p class="muted tiny">None recorded.</p>'}<p class="lh-caption">${e.warnings.map(esc).join(' ')}</p></div>`;}
function lhCorrelation(){const c=S.lh.corr;const labels={fever_onset:'Fever onset documented',fever_resolution_documented:'Fever resolution documented',doctor_consultation:'Doctor consultation',laboratory_test:'Laboratory test',medication_prescribed:'Antibiotic prescribed',documented_administration_start:'Documented administration start',documented_administration:'Documented administration',follow_up_visit:'Follow-up visit'};return `<div class="lh-grid2"><div class="card"><h2>Evidence timeline</h2><p class="muted" style="font-size:13px">Fever onset → consultation → laboratory → prescription → documented administration → follow-up. Only dated evidence appears.</p><div class="lh-steps">${c.events.map(e=>`<div class="lh-step ${e.step}"><span class="lh-when">${fmt(e.date)}</span><span class="lh-badge gray">${labels[e.step]||e.step}</span> ${esc(e.title)}${e.status?' · '+esc(e.status.replaceAll('_',' ')):''}${e.certainty&&e.certainty!=='exact'?' · <span class="lh-badge warn">date '+esc(e.certainty)+'</span>':''} ${lhSrc(e.source_document_id,e.source_page)}</div>`).join('')||empty('No dated events yet.')}</div></div><div class="stack"><div class="card"><h2>Fever without a documented antibiotic</h2>${c.fever_episodes_without_documented_antibiotic.map(f=>`<div class="lh-quote">${esc(f.title)}<small>${fmt(f.first_documented_on)}</small></div>`).join('')||'<p class="muted tiny">None.</p>'}</div><div class="card"><h2>Antibiotic without a documented fever</h2>${c.antibiotic_courses_without_documented_fever.map(a=>`<div class="lh-quote">${esc(a.generic_name)}<small>${fmt(a.prescribed_on)}</small></div>`).join('')||'<p class="muted tiny">None.</p>'}</div><div class="note">${c.warnings.map(esc).join(' ')}</div></div></div>`;}
/* ---------------------------------------------------------------- parent entries & review */
function lhParent(){return `<div class="lh-grid2"><div class="card"><h2>Add information the documents do not contain</h2><p class="muted" style="font-size:13px">Home fevers, medicines you gave, hospital visits. Entries are always labelled <b>parent-reported</b> and kept separate from clinician documents. Corrections keep the previous version.</p><form id="lh-parent-form"><label class="field">What are you recording?<select name="kind"><option value="fever">A fever</option><option value="medicine">A medicine that was given</option><option value="hospital_visit">A hospital or clinic visit</option><option value="note">A note</option></select></label><div class="formgrid">${field('Fever onset / event date','started_on','date')}${field('Fever end date (if known)','ended_on','date')}</div><div class="formgrid">${field('Highest temperature measured','temperature','text','',false,'maxlength="12" placeholder="e.g. 101.2"')}<label class="field">Unit<select name="temperature_unit"><option value="">Not measured</option><option value="F">°F</option><option value="C">°C</option></select></label></div>${textArea('Symptoms','symptoms')}<div class="formgrid">${field('Medicine given (brand or generic)','medicine_name','text','',false,'maxlength="150"')}${field('Dose given','medicine_dose','text','',false,'maxlength="120"')}</div><div class="formgrid">${field('Actual date given','administered_on','date')}${field('Actual time given (HH:MM)','administered_time','time')}</div>${field('Hospital / clinic visit (name and reason)','hospital_visit','text','',false,'maxlength="500"')}${textArea('Personal notes','notes')}<div class="alert">Your entry becomes a parent-reported record immediately. It never changes a clinician document and it is counted separately until you mark it verified.</div><div class="formfoot"><button class="btn">Save parent-reported entry</button></div></form></div><div class="card"><h2>Your entries (${S.lh.parents.length})</h2>${S.lh.parents.map(e=>`<div class="lh-episode"><div class="lh-row"><h3>${esc(e.kind.replaceAll('_',' '))}</h3><span class="lh-badge parent">Parent-reported</span>${e.status==='withdrawn'?'<span class="lh-badge gray">Withdrawn</span>':''}<span class="lh-badge gray">v${e.version}</span></div><div class="lh-kv"><div><span>Dates</span>${fmt(e.started_on)}${e.ended_on?' → '+fmt(e.ended_on):''}</div>${e.temperature?`<div><span>Temperature</span>${esc(e.temperature)} °${esc(e.temperature_unit)}</div>`:''}${e.medicine_name?`<div><span>Medicine</span>${esc(e.medicine_name)} ${esc(e.medicine_dose)} · ${fmt(e.administered_on)} ${esc(e.administered_time)}</div>`:''}${e.symptoms?`<div><span>Symptoms</span>${esc(e.symptoms)}</div>`:''}${e.hospital_visit?`<div><span>Visit</span>${esc(e.hospital_visit)}</div>`:''}${e.notes?`<div><span>Notes</span>${esc(e.notes)}</div>`:''}</div>${e.revisions.length?`<details><summary>Previous versions (${e.revisions.length})</summary>${e.revisions.map(r=>`<div class="lh-quote">${dtfmt(r.changed_at)}<small>${esc(JSON.stringify(Object.fromEntries(Object.entries(r.previous_values).filter(([k])=>['started_on','ended_on','temperature','symptoms','medicine_name','medicine_dose','administered_on','notes','status'].includes(k)))))}</small></div>`).join('')}</details>`:''}<div class="lh-row">${e.status==='active'?lhBtn('Correct','lh-parent-edit',`data-id="${e.id}"`)+lhBtn('Withdraw','lh-parent-withdraw',`data-id="${e.id}"`,'btn ghost small'):''}</div></div>`).join('')||empty('No parent-reported entries yet.')}</div></div>`;}
function lhReview(){const r=S.lh.review;return `<div class="card"><div class="sectionhead"><h2>Fever-event review table (${r.fever_review_table.length})</h2><div class="pillrow"><button class="btn alt small" data-action="lh-scan">Scan transcribed pages for mentions</button><button class="btn alt small" data-action="lh-summary">↓ Evidence summary</button></div></div><div class="tablewrap"><table class="lh-table"><thead><tr><th>#</th><th>Episode</th><th>First</th><th>Last</th><th>Duration</th><th>Temp</th><th>Certainty</th><th>Origin</th><th>Status</th><th>Source link</th><th>Evidence</th></tr></thead><tbody>${r.fever_review_table.map(x=>`<tr><td>${x.id}</td><td>${esc(x.title)}${x.needs_parent_check?`<div class="lh-flag">${esc(x.needs_parent_check)}</div>`:''}</td><td>${fmt(x.first_documented_on)}</td><td>${fmt(x.last_documented_on)}</td><td>${x.documented_duration_days!=null?x.documented_duration_days+' d':''} ${esc(x.duration_text)}</td><td>${esc(x.highest_temperature)}</td><td>${esc(x.date_certainty)}</td><td>${esc(x.origin.replaceAll('_',' '))}</td><td>${lhVer(x.verification_status)}</td><td>${x.source_link_valid?'<span class="lh-badge ok">valid</span>':'<span class="lh-badge warn">check</span>'}</td><td>${x.evidence_count} ${x.evidence_links_valid?'':'<span class="lh-badge warn">link issue</span>'}</td></tr>`).join('')||'<tr><td colspan="11">'+empty('No fever rows.')+'</td></tr>'}</tbody></table></div></div>
 <div class="card lh-section"><h2>Antibiotic-course review table (${r.antibiotic_review_table.length})</h2><div class="tablewrap"><table class="lh-table"><thead><tr><th>#</th><th>Ingredient</th><th>Brand</th><th>Route</th><th>Prescribed</th><th>Actual</th><th>Duration</th><th>Status</th><th>Setting</th><th>Counted</th><th>Days</th><th>Doses</th><th>Classification</th><th>Verification</th><th>Source</th></tr></thead><tbody>${r.antibiotic_review_table.map(x=>`<tr><td>${x.id}</td><td>${esc(x.generic_name)}</td><td>${esc(x.brand_name)}</td><td>${esc(x.route)}</td><td>${fmt(x.prescribed_on)}</td><td>${fmt(x.actual_start)}→${fmt(x.actual_stop)}</td><td>${esc(String(x.prescribed_duration||''))}</td><td>${lhStatus(x.administration_status)[0]}</td><td>${esc(x.setting.replaceAll('_',' '))}</td><td>${x.counted_as_separate_course?'yes':x.continuation_of_id?'continuation of #'+x.continuation_of_id:'no'}</td><td>${x.exposure_days}</td><td>${x.administrations}</td><td>${x.classification.is_antibiotic===true?'<span class="lh-badge ok">'+esc(x.classification.class)+'</span>':'<span class="lh-badge warn">verify ingredient</span>'}${x.uncertain_fields?`<div class="muted tiny">uncertain: ${esc(x.uncertain_fields)}</div>`:''}</td><td>${lhVer(x.verification_status)}</td><td>${x.source_link_valid&&x.evidence_links_valid?'<span class="lh-badge ok">valid</span>':'<span class="lh-badge warn">check</span>'}</td></tr>`).join('')||'<tr><td colspan="15">'+empty('No antibiotic rows.')+'</td></tr>'}</tbody></table></div></div>
 <div class="card lh-section"><h2>Duplicates and uncertain entries (${r.duplicates_and_uncertain.length})</h2>${r.duplicates_and_uncertain.map(f=>`<div class="lh-flag"><b>${esc(f.type.replaceAll('_',' '))}</b> · ${(f.ids||f.course_ids).map(i=>'#'+i).join(', ')}: ${esc(f.detail)}</div>`).join('')||'<p class="muted tiny">None detected.</p>'}<h3 class="lh-section">Source-document link validation</h3>${r.source_links.invalid.length?r.source_links.invalid.map(x=>`<div class="lh-flag">#${x.id} ${esc(x.title||x.generic_name)}: source or evidence page is outside the stored document.</div>`).join(''):'<p class="muted tiny">All source and evidence links point to stored pages.</p>'}${S.lh.scan?`<h3 class="lh-section">Mentions found in transcribed page text (${S.lh.scan.length} pages)</h3><p class="muted tiny">Candidates only; compare with the original page before creating a record.</p>${S.lh.scan.map(pg=>`<div class="lh-quote"><b>${esc(pg.source_ref||('#'+pg.document_id))}</b> page ${pg.page} · ${esc(pg.category)} · ${fmt(pg.record_date)} ${lhSrc(pg.document_id,pg.page)}${pg.fever_mentions.map(m=>`<small>🌡 ${esc(m.line)}${m.temperatures.length?' · '+m.temperatures.join(', '):''}${m.duration?' · '+esc(m.duration.text):''}</small>`).join('')}${pg.antibiotic_mentions.map(m=>`<small>💊 ${esc(m.line)} · ${m.antibiotics.map(a=>esc(a.generic)).join(', ')} · ${m.context==='culture_susceptibility_list'?'culture susceptibility list (not an exposure)':'prescription or note'}</small>`).join('')}</div>`).join('')}`:''}</div>`;}
/* ---------------------------------------------------------------- modals */
function lhForm(kind,data={}){const x=data;const sel=(name,opts,val)=>`<label class="field">${esc(name.replaceAll('_',' '))}<select name="${name}">${opts.map(([v,l])=>`<option value="${v}" ${String(val||'')===v?'selected':''}>${l}</option>`).join('')}</select></label>`;const episodes=S.lh.dash.illnesses.illnesses.map(i=>i.episode);const epi=sel('illness_episode_id',[['','Not linked']].concat(episodes.map(e=>[String(e.id),e.title])),x.illness_episode_id);const adm=sel('admission_id',[['','Not linked']].concat(S.admissions.map(a=>[String(a.id),`${a.facility} ${a.admitted_on}`])),x.admission_id);
 if(kind==='fever')return `<form id="lh-fever-form"><input type="hidden" name="id" value="${x.id||''}"/>${field('Episode title','title','text',x.title,true,'maxlength="180"')}<div class="formgrid">${field('First documented fever date','first_documented_on','date',x.first_documented_on)}${field('Last documented fever date','last_documented_on','date',x.last_documented_on)}</div><div class="formgrid">${field('Documented fever days (leave blank if only written as text)','documented_fever_days','number',x.documented_fever_days??'',false,'min="0" max="120"')}${field('Duration exactly as written','duration_text','text',x.duration_text,false,'maxlength="200" placeholder="e.g. fever x 3 days"')}</div>${sel('date_certainty',[['exact','Exact dates on the document'],['approximate','Approximate (for example “since 1 day”)'],['unknown','Unknown']],x.date_certainty||'unknown')}<div class="formgrid">${field('Highest recorded temperature','highest_temperature','text',x.highest_temperature,false,'maxlength="12"')}${sel('temperature_unit',[['','No unit / not recorded'],['F','°F'],['C','°C']],x.temperature_unit)}</div>${textArea('Associated symptoms','symptoms',x.symptoms)}${textArea('Diagnosis exactly as documented','documented_diagnosis',x.documented_diagnosis)}${field('Antipyretics prescribed or given (as written)','antipyretics','text',x.antipyretics,false,'maxlength="500"')}<div class="formgrid">${field('Date fever resolution was documented','resolution_documented_on','date',x.resolution_documented_on)}<label class="check"><input type="checkbox" name="hospitalized" ${x.hospitalized?'checked':''}/> Hospitalization occurred</label></div>${epi}${adm}${docSelect(x.source_document_id)}${field('Source page','source_page','number',x.source_page||1,true,'min="1" max="35"')}${field('Quoted wording from the page (saved as evidence)','quoted_text','text','',false,'maxlength="2000"')}${textArea('What should the parent double-check?','needs_parent_check',x.needs_parent_check)}${textArea('Notes','notes',x.notes)}<div class="alert">Enter only what the document says. Do not infer fever from a paracetamol or antibiotic prescription.</div><div class="formfoot"><button class="btn">${x.id?'Save revision (re-verification needed)':'Save clinician-documented episode'}</button></div></form>`;
 if(kind==='course')return `<form id="lh-course-form"><input type="hidden" name="id" value="${x.id||''}"/><div class="formgrid">${field('Medicine as written (brand or generic)','generic_name','text',x.brand_name||x.generic_name,true,'maxlength="120"')}${field('Brand name','brand_name','text',x.brand_name,false,'maxlength="120"')}</div><div id="lh-drug-check" class="muted tiny" style="margin:-6px 0 10px">${x.drug_class?'Class: '+esc(x.drug_class):'Type the name to check it against the active-ingredient table.'}</div><div class="formgrid">${sel('route',[['oral','Oral'],['IV','IV'],['IM','IM'],['other','Other'],['unknown','Unknown']],x.route||'unknown')}${sel('setting',[['outpatient','Outpatient'],['inpatient','Inpatient (hospital)'],['discharge_prescription','Discharge prescription'],['unknown','Unknown']],x.setting||'unknown')}</div><div class="formgrid">${field('Dose as written','dose','text',x.dose,false,'maxlength="120"')}${field('Frequency as written','frequency','text',x.frequency,false,'maxlength="120"')}</div><div class="formgrid">${field('Date prescribed','prescribed_on','date',x.prescribed_on)}${field('Prescribed duration (days)','prescribed_duration_days','number',x.prescribed_duration_days??'',false,'min="1" max="120"')}</div>${field('Prescribed duration exactly as written','prescribed_duration_text','text',x.prescribed_duration_text,false,'maxlength="120"')}<div class="formgrid">${field('Actual start (documented)','actual_start','date',x.actual_start)}${field('Actual stop (documented)','actual_stop','date',x.actual_stop)}</div>${sel('administration_status',[['prescribed_only','Prescribed only (no evidence it was given)'],['scheduled','Scheduled (appointments arranged)'],['confirmed_administered','Confirmed administered (chart or caregiver record)'],['unknown','Unknown'],['not_received','Not received / culture-only']],x.administration_status||'unknown')}<div class="formgrid">${field('Prescribing doctor','prescribing_doctor','text',x.prescribing_doctor,false,'maxlength="180"')}${field('Facility','facility','text',x.facility,false,'maxlength="180"')}</div>${field('Associated illness / indication as written','indication','text',x.indication,false,'maxlength="1000"')}${epi}${adm}${sel('fever_episode_id',[['','Not linked']].concat(S.lh.dash.fever.episodes.map(f=>[String(f.id),f.title])),x.fever_episode_id)}${sel('continuation_of_id',[['','New course']].concat(S.lh.dash.antibiotics.courses.filter(c=>c.id!==x.id).map(c=>[String(c.id),`#${c.id} ${c.generic_name} ${c.route} ${c.prescribed_on||c.actual_start||''}`])),x.continuation_of_id)}<p class="muted tiny">Choose a continuation when this is a renewal or IV→oral switch of the same agent in the same illness; it will not be counted twice.</p>${docSelect(x.source_document_id)}${field('Source page','source_page','number',x.source_page||1,true,'min="1" max="35"')}${field('Quoted wording from the page (saved as evidence)','quoted_text','text','',false,'maxlength="2000"')}${field('Fields you could not read confidently (comma separated)','uncertain_fields','text',x.uncertain_fields,false,'maxlength="250"')}${textArea('What should the parent double-check?','needs_parent_check',x.needs_parent_check)}${textArea('Notes','notes',x.notes)}<label class="check"><input type="checkbox" name="allow_unrecognised_ingredient"/> The ingredient is not in the table; keep it as an unclassified candidate (excluded from counts).</label><div class="formfoot"><button class="btn">${x.id?'Save revision (re-verification needed)':'Save antibiotic record'}</button></div></form>`;
 if(kind==='admin')return `<form id="lh-admin-form"><input type="hidden" name="course_id" value="${x.course_id}"/><p class="muted">${esc(x.label)}</p><div class="formgrid">${field('Date administered','administered_on','date','',true)}${field('Time (HH:MM)','administered_time','time')}</div><div class="formgrid">${field('Dose as recorded','dose','text','',false,'maxlength="120"')}${sel('route',[['oral','Oral'],['IV','IV'],['IM','IM'],['other','Other'],['unknown','Unknown']],x.route)}</div>${sel('source',[['caregiver_report','Caregiver report (I gave it / saw it given)'],['nursing_chart','Hospital nursing / medication chart'],['discharge_summary','Statement in a discharge summary']],'caregiver_report')}${docSelect()}${field('Source page','source_page','number',1,true,'min="1" max="35"')}${textArea('Note','note')}<div class="alert">A chart source needs the page attached. Each record counts as one documented administration (Metric D) and marks that calendar day as an exposure day (Metric C).</div><div class="formfoot"><button class="btn">Record administration</button></div></form>`;
 if(kind==='parent')return lhParent().match(/<form id="lh-parent-form">[\s\S]*?<\/form>/)[0].replace('<form id="lh-parent-form">',`<form id="lh-parent-form"><input type="hidden" name="id" value="${x.id}"/>`).replace(/name="kind">/,`name="kind" data-fixed="${x.kind}">`).replace(/value="(fever|medicine|hospital_visit|note)"/g,(m,v)=>v===x.kind?m+' selected':m).replace(/name="(started_on|ended_on|temperature|symptoms|medicine_name|medicine_dose|administered_on|administered_time|hospital_visit|notes)"( value="")?/g,(m,n)=>`name="${n}" value="${esc(x[n]||'')}"`).replace(/<textarea name="(symptoms|notes)">/g,(m,n)=>`<textarea name="${n}">${esc(x[n]||'')}`).replace(/<option value="(F|C|)"/g,(m,v)=>v===(x.temperature_unit||'')?m+' selected':m).replace('Save parent-reported entry','Save correction (previous version kept)');
 return '';}
const lhBaseModal=modalHtml;
modalHtml=function(){const x=S.prefill||{};
 if(S.modal==='lh-contrib'){const c=S.lh.contrib;return dialog(c.title,`<p class="muted" style="font-size:13px">${esc(c.note||'')}</p>${c.rows.map(r=>`<div class="entry"><div class="entrybody"><b>${esc(r.title)}</b><div class="desc">${esc(r.detail||'')}</div></div>${r.entity&&r.id?lhBtn('Evidence','lh-evidence',`data-entity="${r.entity}" data-id="${r.id}"`):''}${r.doc?lhSrc(r.doc,r.page):''}</div>`).join('')||empty('No contributing records.')}`);}
 if(S.modal==='lh-evidence'){const e=S.lh.evidence;if(!e)return dialog('Original evidence','<div class="loading">Loading…</div>');return dialog(e.title,`<div class="lh-evidence-grid"><section><div class="sectionhead"><h3>Original page</h3><span class="muted tiny" id="lh-page-label">${esc(e.current?lhRef(e.current.id,e.current.page):'No page attached')}</span></div>${e.current?`<img id="lh-page-img" alt="Original medical document page" src="${S.lh.pageUrl||''}"/>`:empty('This record has no source page. Parent-reported entries never have one.')}</section><section>${e.summary}<h3 style="margin-top:14px">Quoted evidence (${e.items.length})</h3>${e.items.map(i=>`<div class="lh-quote">“${esc(i.quoted_text||'(page reference only)')}”<small>${esc(i.evidence_kind.replaceAll('_',' '))} · ${fmt(i.observed_on)} · certainty ${esc(i.certainty)} · ${i.source_document_id?`<button class="btn ghost small" data-action="lh-page" data-id="${i.source_document_id}" data-page="${i.source_page}" data-inline="1">${esc(lhRef(i.source_document_id,i.source_page))}</button>`:'no page'}</small></div>`).join('')||'<p class="muted tiny">No quoted passage attached yet.</p>'}${e.entity!=='illness_episode'?`<form id="lh-evidence-form" class="section-gap"><input type="hidden" name="entity" value="${e.entity}"/><input type="hidden" name="entity_id" value="${e.id}"/><h4>Attach another passage</h4>${docSelect()}<div class="formgrid">${field('Page','source_page','number',1,true,'min="1" max="35"')}${field('Observed on','observed_on','date')}</div>${field('Quoted wording','quoted_text','text','',true,'maxlength="2000"')}<div class="formfoot"><button class="btn alt small">Attach evidence</button></div></form>`:''}</section></div>`,true);}
 if(S.modal==='lh-day'){const d=S.lh.day;return dialog(`Records on ${fmt(d.day)}`,`${d.fever.map(f=>`<div class="entry"><div class="entrybody"><b>${esc(f.title)}</b><div class="desc">${f.origin==='parent_report'?'Parent-reported':'Clinician-documented'} fever · ${esc(f.date_certainty)} dates · ${f.verification_status}</div></div>${lhBtn('Evidence','lh-evidence',`data-entity="fever_episode" data-id="${f.id}"`)}</div>`).join('')}${d.abx.map(c=>`<div class="entry"><div class="entrybody"><b>${esc(c.generic_name)} · ${esc(c.route)}</b><div class="desc">Confirmed administration day · ${lhStatus(c.administration_status)[0]}</div></div>${lhBtn('Evidence','lh-evidence',`data-entity="antibiotic_course" data-id="${c.id}"`)}</div>`).join('')}`);}
 if(S.modal==='lh-fever-form')return dialog(x.id?'Revise fever episode':'Clinician-documented fever episode',lhForm('fever',x));
 if(S.modal==='lh-course-form')return dialog(x.id?'Revise antibiotic record':'Antibiotic record from an original document',lhForm('course',x));
 if(S.modal==='lh-admin-form')return dialog('Documented administration',lhForm('admin',x));
 if(S.modal==='lh-parent-form')return dialog('Correct a parent-reported entry',lhForm('parent',x));
 if(S.modal==='lh-text')return dialog(x.title,`<div class="pre">${esc(x.text)}</div>`);
 return lhBaseModal();};
async function lhShowPage(id,page,inline){try{const r=await request(`/documents/${id}/pages/${page||1}`);if(S.lh.pageUrl)URL.revokeObjectURL(S.lh.pageUrl);S.lh.pageUrl=URL.createObjectURL(await r.blob());if(inline&&S.modal==='lh-evidence'){S.lh.evidence.current={id:Number(id),page:Number(page)};const img=el('#lh-page-img');if(img){img.src=S.lh.pageUrl;el('#lh-page-label').textContent=lhRef(Number(id),Number(page));}else render();}else{S.sourceURL=S.lh.pageUrl;openModal('source');}}catch(e){fail(e);}}
async function lhOpenEvidence(entity,id){S.modal='lh-evidence';S.lh.evidence=null;render();const d=S.lh.dash;let summary='',title='',current=null;
 if(entity==='fever_episode'){const f=d.fever.episodes.find(f=>f.id===+id);title=f?f.title:'Fever episode';if(f){summary=`<div class="lh-row">${lhOrigin(f.origin)}${lhVer(f.verification_status)}</div><div class="lh-kv"><div><span>Dates</span>${fmt(f.first_documented_on)} → ${fmt(f.last_documented_on)} (${esc(f.date_certainty)})</div><div><span>Duration</span>${esc(f.duration_text||(f.documented_duration_days!=null?f.documented_duration_days+' days':'not documented'))}</div><div><span>Temperature</span>${esc(f.highest_temperature||'not recorded')} ${esc(f.temperature_unit)}</div><div><span>Diagnosis</span>${esc(f.documented_diagnosis||'not documented')}</div></div>`;if(f.source_document_id)current={id:f.source_document_id,page:f.source_page};}}
 else if(entity==='antibiotic_course'){const c=d.antibiotics.courses.find(c=>c.id===+id);title=c?`${c.generic_name} · ${c.route}`:'Antibiotic course';if(c){summary=`<div class="lh-row"><span class="lh-badge ${lhStatus(c.administration_status)[1]}">${lhStatus(c.administration_status)[0]}</span>${lhOrigin(c.origin)}${lhVer(c.verification_status)}</div><div class="lh-kv"><div><span>Prescribed</span>${fmt(c.prescribed_on)} · ${esc(c.dose)} ${esc(c.frequency)}</div><div><span>Duration</span>${esc(c.prescribed_duration_text||(c.prescribed_duration_days?c.prescribed_duration_days+' days':'not documented'))}</div><div><span>Actual</span>${fmt(c.actual_start)} → ${fmt(c.actual_stop)}</div><div><span>Confirmed days</span>${c.exposure_days.length}${c.exposure_days.length?': '+c.exposure_days.join(', '):''}</div><div><span>Dose records</span>${c.administrations.length}</div><div><span>Illness</span>${esc(c.illness||c.indication||'not linked')}</div></div>${c.needs_parent_check?`<div class="lh-flag">${esc(c.needs_parent_check)}</div>`:''}`;if(c.source_document_id)current={id:c.source_document_id,page:c.source_page};}}
 try{const r=await request(`/patients/${S.pid}/lifetime/evidence?entity=${entity}&entity_id=${id}`);if(!current&&r.items[0]?.source_document_id)current={id:r.items[0].source_document_id,page:r.items[0].source_page};S.lh.evidence={entity,id:+id,title,summary,items:r.items,current};if(current){const p=await request(`/documents/${current.id}/pages/${current.page||1}`);if(S.lh.pageUrl)URL.revokeObjectURL(S.lh.pageUrl);S.lh.pageUrl=URL.createObjectURL(await p.blob());}render();}catch(e){fail(e);closeModal();}}
function lhContrib(key){const d=S.lh.dash;const f=d.fever,a=d.antibiotics;let rows=[],title='',note='';
 const feverRow=e=>({title:e.title,detail:`${fmt(e.first_documented_on)} → ${fmt(e.last_documented_on)} · ${e.origin==='parent_report'?'parent-reported':'clinician-documented'} · ${e.verification_status}`,entity:'fever_episode',id:e.id});
 const abxRow=c=>({title:`${c.generic_name} · ${c.route}`,detail:`${fmt(c.prescribed_on||c.actual_start)} · ${lhStatus(c.administration_status)[0]} · ${c.verification_status}${c.continuation_of_id?' · continuation of #'+c.continuation_of_id:''}`,entity:'antibiotic_course',id:c.id});
 if(key==='fever_episodes'){title='Documented fever episodes';rows=f.episodes.map(feverRow);}
 else if(key==='distinct_antibiotics'){title='Distinct antibiotics';note='One row per active ingredient; brands normalised.';rows=a.metrics.A_distinct_antibiotics.contributors.map(g=>({title:g.generic_name,detail:`${g.drug_class} · course records #${g.course_ids.join(', #')}`,entity:'antibiotic_course',id:g.course_ids[0]}));}
 else if(key==='antibiotic_courses'){title='Documented antibiotic courses';rows=a.courses.filter(c=>a.metrics.B_antibiotic_courses.contributors.includes(c.id)).map(abxRow);}
 else if(key==='exposure_days'){title='Confirmed antibiotic-exposure days';note='Calendar days with a dated administration record. A day with two antibiotics counts once.';rows=a.metrics.C_exposure_days.overall_dates.map(day=>({title:fmt(day),detail:a.courses.filter(c=>c.exposure_days.includes(day)).map(c=>c.generic_name+' ('+c.route+')').join(', ')}));if(a.metrics.C_exposure_days.undated_inpatient_windows.length)rows.push(...a.metrics.C_exposure_days.undated_inpatient_windows.map(w=>({title:`${w.generic_name}: hospital stay ${fmt(w.window_start)}–${fmt(w.window_end)} (at most ${w.at_most_days} days, not counted)`,detail:w.note,entity:'antibiotic_course',id:w.course_id})));}
 else if(key==='administrations'){title='Documented administrations';rows=a.courses.flatMap(c=>c.administrations.map(x=>({title:`${c.generic_name} · ${fmt(x.administered_on)} ${x.administered_time}`,detail:`${x.source.replaceAll('_',' ')} · ${x.dose||'dose not recorded'}`,entity:'antibiotic_course',id:c.id,doc:x.source_document_id,page:x.source_page})));}
 else if(key==='hospitalizations'){title='Hospitalizations';rows=S.admissions.map(x=>({title:x.facility,detail:`${fmt(x.admitted_on)} → ${fmt(x.discharged_on)} · ${x.diagnosis||'diagnosis not documented'}`,doc:x.source_document_id,page:x.source_page}));}
 else if(key==='illness_episodes'){title='Illness episodes';rows=d.illnesses.illnesses.map(i=>({title:i.episode.title,detail:`${fmt(i.episode.started_on)} → ${fmt(i.episode.ended_on)} · ${i.documented_diagnosis||'diagnosis not documented'}`,doc:i.episode.source_document_id,page:i.episode.source_page}));}
 else if(key==='documents'){title='Medical reports';rows=S.docs.map(x=>({title:x.title,detail:`${x.source_ref||''} · ${x.category} · ${fmt(x.record_date)} · ${x.page_count} page(s)`,doc:x.id,page:1}));}
 else if(key==='pending'){title='Records awaiting your verification';rows=f.episodes.filter(e=>e.verification_status==='needs_verification').map(feverRow).concat(a.courses.filter(c=>c.verification_status==='needs_verification').map(abxRow)).concat(S.lh.parents.filter(p=>p.status==='active').map(p=>({title:`Parent entry: ${p.kind.replaceAll('_',' ')}`,detail:`${fmt(p.started_on||p.administered_on)} · v${p.version}`})));}
 S.lh.contrib={title,note,rows};S.modal='lh-contrib';render();}
const lhBaseExecute=execute;
execute=async function(action,id,b){
 if(action==='lh-retry'){S.lh.error=null;S.lh.loaded=false;return lhLoad(true);}
 if(action==='lh-tab'){S.lh.tab=b.dataset.key;render();return;}
 if(action==='lh-contrib')return lhContrib(b.dataset.key);
 if(action==='lh-list'){const ids=(b.dataset.ids||'').split(',').filter(Boolean).map(Number);const d=S.lh.dash;const rows=b.dataset.kind==='fever'?d.fever.episodes.filter(e=>ids.includes(e.id)).map(e=>({title:e.title,detail:`${fmt(e.first_documented_on)} → ${fmt(e.last_documented_on)} · ${e.date_certainty} · ${e.verification_status}`,entity:'fever_episode',id:e.id})):d.antibiotics.courses.filter(c=>ids.includes(c.id)).map(c=>({title:`${c.generic_name} · ${c.route}`,detail:`${fmt(c.prescribed_on||c.actual_start)} · ${lhStatus(c.administration_status)[0]} · ${c.verification_status}${c.unclassified?' · unrecognised name':''}`,entity:'antibiotic_course',id:c.id}));S.lh.contrib={title:'Contributing records',rows};S.modal='lh-contrib';render();return;}
 if(action==='lh-evidence')return lhOpenEvidence(b.dataset.entity,b.dataset.id);
 if(action==='lh-page')return lhShowPage(id,b.dataset.page,!!b.dataset.inline);
 if(action==='lh-day'){const day=b.dataset.day;const d=S.lh.dash;S.lh.day={day,fever:d.fever.episodes.filter(e=>e.calendar_days.includes(day)),abx:d.antibiotics.courses.filter(c=>c.exposure_days.includes(day))};S.modal='lh-day';render();return;}
 if(action==='lh-verify'){const status=b.dataset.status;if(status==='verified'&&!confirm('Have you compared this record with the original page (dates, name, dose, duration)? Mark it verified only if every field matches.'))return;const note=status==='rejected'?prompt('Why is this record wrong? (kept in the record history)')||'':'';await request(`/lifetime/${b.dataset.entity}/${id}/verify`,{method:'POST',json:{status,checked_against_original:status==='verified',note}});toast(status==='verified'?'Marked verified. Verified counts updated.':'Record rejected; it is excluded from counts but kept in history.');return lhLoad(true);}
 if(action==='lh-fever-new')return openModal('lh-fever-form',{});
 if(action==='lh-fever-edit')return openModal('lh-fever-form',S.lh.dash.fever.episodes.find(e=>e.id===+id));
 if(action==='lh-course-new')return openModal('lh-course-form',{});
 if(action==='lh-course-edit')return openModal('lh-course-form',S.lh.dash.antibiotics.courses.find(c=>c.id===+id));
 if(action==='lh-admin-new'){const c=S.lh.dash.antibiotics.courses.find(c=>c.id===+id);return openModal('lh-admin-form',{course_id:c.id,route:c.route,label:`${c.generic_name} · ${c.route} · prescribed ${fmt(c.prescribed_on)}`});}
 if(action==='lh-parent-new'){S.tab='lifetime';S.lh.tab='parent';render();window.scrollTo({top:0,behavior:'smooth'});return;}
 if(action==='lh-parent-edit')return openModal('lh-parent-form',S.lh.parents.find(p=>p.id===+id));
 if(action==='lh-parent-withdraw'){if(!confirm('Withdraw this entry? It stays in your history but is removed from the counts.'))return;await request(`/lifetime/parent-entries/${id}/withdraw`,{method:'POST'});return lhLoad(true);}
 if(action==='lh-summary')return downloadEndpoint(`/patients/${S.pid}/lifetime/summary`,'lifetime-health-summary.txt');
 if(action==='lh-scan'){const r=await request(`/patients/${S.pid}/lifetime/scan`);S.lh.scan=r.pages;render();return;}
 return lhBaseExecute(action,id,b);};
const lhBaseSubmit=submitForm;
submitForm=async function(f){const fd=new FormData(f),o=Object.fromEntries(fd);const pid=S.pid;const fid=f.getAttribute('id');
 const nulls=keys=>{for(const k of keys)if(o[k]==='')o[k]=null;};
 const ints=keys=>{for(const k of keys)if(k in o)o[k]=o[k]===''||o[k]===null?null:Number(o[k]);};
 if(fid==='lh-parent-form'){const id=o.id;delete o.id;nulls(['started_on','ended_on','administered_on']);await request(id?`/lifetime/parent-entries/${id}`:`/patients/${pid}/lifetime/parent-entries`,{method:id?'PATCH':'POST',json:o});toast(id?'Correction saved; the previous version is kept.':'Parent-reported entry saved and labelled as such.');S.modal='';return lhLoad(true);}
 if(fid==='lh-fever-form'){const id=o.id;delete o.id;const quoted=o.quoted_text;delete o.quoted_text;o.hospitalized=fd.has('hospitalized');nulls(['first_documented_on','last_documented_on','resolution_documented_on','documented_fever_days','illness_episode_id','admission_id','source_document_id']);ints(['documented_fever_days','illness_episode_id','admission_id','source_document_id','source_page']);o.evidence=quoted&&o.source_document_id?[{source_document_id:o.source_document_id,source_page:o.source_page,quoted_text:quoted,evidence_kind:'fever_mention',observed_on:o.first_documented_on,certainty:'medium'}]:[];await request(id?`/lifetime/fever/${id}`:`/patients/${pid}/lifetime/fever`,{method:id?'PATCH':'POST',json:o});toast('Fever episode saved. It stays “needs verification” until you check it against the page.');S.modal='';return lhLoad(true);}
 if(fid==='lh-course-form'){const id=o.id;delete o.id;const quoted=o.quoted_text;delete o.quoted_text;o.allow_unrecognised_ingredient=fd.has('allow_unrecognised_ingredient');nulls(['prescribed_on','planned_start','planned_end','actual_start','actual_stop','prescribed_duration_days','administered_duration_days','illness_episode_id','admission_id','fever_episode_id','continuation_of_id','source_document_id']);ints(['prescribed_duration_days','illness_episode_id','admission_id','fever_episode_id','continuation_of_id','source_document_id','source_page']);o.evidence=quoted&&o.source_document_id?[{source_document_id:o.source_document_id,source_page:o.source_page,quoted_text:quoted,evidence_kind:'prescription',observed_on:o.prescribed_on||o.actual_start,certainty:'medium'}]:[];await request(id?`/lifetime/antibiotics/${id}`:`/patients/${pid}/lifetime/antibiotics`,{method:id?'PATCH':'POST',json:o});toast('Antibiotic record saved.');S.modal='';return lhLoad(true);}
 if(fid==='lh-admin-form'){const cid=o.course_id;delete o.course_id;nulls(['source_document_id']);ints(['source_document_id','source_page']);o.idempotency_key=crypto.randomUUID().replace(/-/g,'');await request(`/lifetime/antibiotics/${cid}/administrations`,{method:'POST',json:o});toast('Administration recorded.');S.modal='';return lhLoad(true);}
 if(fid==='search-form'){const node=el('#search-results');node.innerHTML='<div class="loading">Finding source records…</div>';try{const r=await request(`/patients/${pid}/lifetime/ask`,{method:'POST',json:{question:o.q}});const structured=r.mode==='lifetime_health_structured'||r.mode==='daily_care_structured';if(!structured&&typeof renderAnswer==='function'){renderAnswer(node,r);return;}node.innerHTML=`<p class="muted tiny">${r.mode==='lifetime_health_structured'?'Lifetime Health · structured answer from documented records':r.mode==='daily_care_structured'?'Daily Care · answer from your journal entries':'Source-grounded record retrieval · no diagnosis inferred'}</p>${structured?`<div class="headnote" style="white-space:pre-wrap">${esc(r.answer)}</div>`:''}${r.evidence.map(e=>`<div class="answer-evidence"><div class="pillrow">${status(e.verified?'Caregiver verified':'Unverified transcription')}<span class="muted tiny">[${esc(e.citation)}]${e.date?' · '+fmt(e.date):''}</span></div><p>${esc(e.statement)}</p>${e.source_document_id?lhSrc(e.source_document_id,e.source_page):''}</div>`).join('')||(r.mode==='lifetime_health_structured'?'':empty(r.answer))}<div class="note">${r.warnings.map(esc).join(' ')}</div>`;}catch(e){node.textContent=e.message;throw e;}return;}
 if(fid==='lh-evidence-form'){const entity=o.entity,eid=o.entity_id;delete o.entity;delete o.entity_id;nulls(['observed_on','source_document_id']);ints(['source_document_id','source_page']);if(!o.source_document_id)throw Error('Choose the document that contains this wording.');await request(`/patients/${pid}/lifetime/evidence?entity=${entity}&entity_id=${eid}`,{method:'POST',json:{...o,evidence_kind:'mention',certainty:'medium'}});toast('Evidence attached.');await lhLoad(true);return lhOpenEvidence(entity,eid);}
 return lhBaseSubmit(f);};
const lhBaseRender=render;
render=function(){if(S.token&&S.patients.length&&S.tab==='lifetime'){el('#app').innerHTML=layout(lifetimeView());return;}lhBaseRender();};
const lhBaseReload=reload;
reload=async function(){await lhBaseReload();if(S.lh.loaded)S.lh.loaded=false;if(S.tab==='lifetime')lhLoad(true);};
document.addEventListener('input',async e=>{if(e.target.name==='generic_name'&&e.target.closest('#lh-course-form')){const v=e.target.value.trim();const node=el('#lh-drug-check');if(!node||v.length<3)return;try{const r=await request(`/lifetime/drug-check?name=${encodeURIComponent(v)}`);node.textContent=r.is_antibiotic===true?`Recognised: ${r.generic} (${r.class})${r.brand_recognized?' · brand normalised':''}`:r.is_antibiotic===false?`Not an antibiotic: ${r.generic}. It cannot be saved as an antibiotic course.`:'Not in the verified ingredient table. Enter the generic name, or allow an unclassified candidate below.';}catch{}}});
document.addEventListener('change',e=>{if(e.target.name==='kind'&&e.target.closest('#lh-parent-form')){const k=e.target.value;const f=e.target.closest('form');const show=(names,on)=>names.forEach(n=>{const node=f.elements[n]?.closest('.field')||f.elements[n]?.closest('label');if(node)node.style.display=on?'':'none';});show(['temperature','temperature_unit','ended_on','symptoms'],k==='fever');show(['medicine_name','medicine_dose','administered_on','administered_time'],k==='medicine'||k==='fever');show(['hospital_visit'],k==='hospital_visit'||k==='fever');}});
